inv_by_id = {}
for inv in data['invoices']:
    inv_by_id = putmap(inv_by_id, inv['id'], inv['amount'])
paid_by_id = {}
for inv in data['invoices']:
    paid_by_id = putmap(paid_by_id, inv['id'], 0)
for row in data['rows']:
    paid_by_id = putmap(paid_by_id, row['invoice'], get(paid_by_id, row['invoice'], 0) + row['amount'])
ids = sorted(keys(inv_by_id))
detail = []
total_amount = 0
total_paid = 0
total_due = 0
total_credit = 0
unpaid_ids = []
for invoice_id in ids:
    amount = inv_by_id[invoice_id]
    paid = paid_by_id[invoice_id]
    due = max(amount - paid, 0)
    credit = max(paid - amount, 0)
    detail = detail + [{'id': invoice_id, 'amount': amount, 'paid': paid, 'due': due, 'credit': credit}]
    total_amount = total_amount + amount
    total_paid = total_paid + paid
    total_due = total_due + due
    total_credit = total_credit + credit
    if due > 0:
        unpaid_ids = unpaid_ids + [invoice_id]
summary = {'amount': total_amount, 'paid': total_paid, 'due': total_due, 'credit': total_credit, 'unpaid_ids': unpaid_ids}
